DROP TABLE IF EXISTS `info`;
CREATE TABLE `info` (
  `INFO_ID` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `INFO_DATE` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
