  `UPDATED_BY` varchar(45) NOT NULL DEFAULT '',
  `CREATED_ON` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `INFO_REMARK` varchar(45) NOT NULL DEFAULT '',
  PRIMARY KEY (`INFO_ID`)
) ENGINE=MyISAM AUTO_INCREMENT=29 DEFAULT CHARSET=utf8;

