INSERT INTO `info` (`INFO_ID`,`INFO_DATE`,`INFO_DESP`,`INFO_STATUS`,`CREATED_BY`,`UPDATED_BY`,`CREATED_ON`,`INFO_REMARK`) VALUES 
 (11,'2009-11-19 00:00:00','New button added in creating bill process. User can now choose to skip step 2 in bill creation or not to. <br />Please click <a href=\"/images/newfunction.jpg\" target=\"_BLANK\">here</a> for futher information.','','','','0000-00-00 00:00:00','New Function'),
 (8,'2009-11-25 00:00:00','Added express way of adding services into bill. Please click <a target=\"_BLANK\"  href=\"http://119.73.212.38/video1.cfm\">here</a> to see how it work.','','','','0000-00-00 00:00:00','New Function'),
 (9,'2009-08-06 00:00:00','Added delivery fax and delivery phone in customer, company and supplier profile to increase the effectiveness of user','','','','0000-00-00 00:00:00','New Function'),
 (10,'2009-11-19 00:00:00','Link to edit bill detail while creating bill has been added to transaction 3 page where user can edit the bill header, agent, term,& etc again will on process adding item. Please refer to images <a href=\"/images/newfunction2.jpg\" target=\"_BLANK\">here</a>','','','','0000-00-00 00:00:00','New Function'),
 (12,'2009-11-25 00:00:00','Project Report is added.','','swdemo','','2009-12-15 10:31:53','New Report'),
 (13,'2009-12-11 00:00:00','New button \"Save\" is added in editing bill process. After the changes made to the header information, you can just click \"Save\" button to save the bill.','','swdemo','','2009-12-15 10:40:56','Enhancement'),
 (14,'2009-12-11 00:00:00','Per item project now is available. You can enable or disable the \"Project by Bill\" function under the General Setup -> Transaction Setup.','','swdemo','','2009-12-15 10:45:33','Enhancement'),
 (15,'2010-01-12 00:00:00','New customer and supplier profile creation in transaction and added new search customer and supplier function. Please click <a target=\"_BLANK\"  href=\"http://119.73.212.38/video2.cfm\">here</a> to see how it work.','','tud09','','0000-00-00 00:00:00','Enhancement'),
 (16,'2010-01-19 00:00:00','New create service, search item, search history item and express add item function have added into IMS. Please click <a target=\"_BLANK\"  href=\"http://119.73.212.38/video3.cfm\">here</a> to see how it work.','','tud09','','2010-01-19 10:16:20','Enhancement'),
 (17,'2010-02-09 00:00:00','New function of symbol maintenance has been added into system','','tud09','','0000-00-00 00:00:00','New Function'),
 (18,'2010-02-09 00:00:00','Packling list function have been added into IMS. Please click <a target=\"_BLANK\"  href=\"http://119.73.212.38/video4.cfm\">here</a> to see how it work.','','tud09','','0000-00-00 00:00:00','New Function'),
 (19,'2010-03-24 00:00:00','Please take note that there will be a urgent critical network circuit replacement from 24th March 2010 1200hrs to 1300hrs Singapore Time. The IMS/AMS services will Not be available during this 1 hour.\r\n\r\nAs a result, IMS customers may experience a distruption of service during the stipulated period. We would like to assure you that the service would resume to normal after this period.\r\n\r\nNetiquette apologizes for any inconvenience caused.\r\n\r\nCustomer can call Netiquette at 62231157 for Singapore and 03-78778955 for Malaysia for any related problem.\r\n\r\nThank you!','','swdemo','swdemo','2010-03-24 08:55:58','URGENT! NETWORK CIRCUIT REPLACEMENT'),
 (20,'2010-03-26 00:00:00','How\'s the Second Unit works? How to maintain Second Unit in the Product Profile?\r\nPlease click <a target=\"_BLANK\"  href=\"http://119.73.212.38/second_unit_function.txt\">here</a> for the sample.','','swdemo','swdemo','2010-03-26 15:53:21','Second Unit Function'),
 (21,'2010-06-15 00:00:00','Voucher profile have been added into IMS. This voucher profile is basically for maintaining voucher for discount purpose of products. Please click <a href=\"/video7.html\">here</a> to see how to enable the voucher profile and how it works.','','ultracai','','2010-06-15 10:11:25','Enhancement'),
 (22,'2010-06-15 00:00:00','New Print Function added in posting to AMS. It is mainly used for user to keep the record of the transaction into the paper work of for the review purpose. Please Click <a href=\"/video6.html\">here</a> to see how it works\r\n','','ultracai','','2010-06-15 10:18:01','Enhancement'),
 (23,'2010-07-09 00:00:00','New Customer Filter in Copy Bill. Allow user to search for customer with ease.','','ultracai','ultrairene','2010-07-09 17:59:15','ENHANCEMENT'),
 (24,'2010-07-09 00:00:00','Added print PDF function in Item Status and Value. Allows user to print Item Status and Value in PDF format','','ultracai','','2010-07-09 18:09:14','New Features'),
 (25,'2010-07-09 00:00:00','Solved the bug which wrong period appear in Copy Bill. ','','ultracai','','2010-07-09 18:11:24','Bug'),
 (26,'2010-10-18 00:00:00','IMS Help Centre has been add into the system. User can access it by click \"HELP\" button at the up-right corner.','','ultracai','','2010-10-18 16:04:57','NEW FUNCTION'),
 (27,'2011-01-25 00:00:00','Dear Valued Customers, \r\nWe will be closed for Chinese New Year from 31st January 2011 until 4th February 2011. Any enquiries please email to siong@netiquette.com.sg OR call 90681161.\r\nOn behalf of the Management, we would like to take this opportunity to thanks all for the wonderful support given to Netiquette Software and wishing you and your management a happy and prosperous lunar new year. \r\n','','ultrairene','','2011-01-25 12:49:12','ANNOUCEMENT'),
 (28,'2011-08-01 00:00:00','Dear Valued Customer/Partners,\r\n\r\n\r\nPlease be advised that Netiquette will be performing a server maintenance, which requires the complete shutdown of the main server system. While the server is offline,  AMS, IMS, Payroll and CRM site will not be accessible.\r\n\r\nWork Starts: 10:00pm Friday, August 12 2011\r\nWork Ends:  08:00am Saturday, August 13 2011\r\n\r\nOur apologies for any inconvenience this may cause.\r\n\r\n\r\n\r\n\r\n- Netiquette Service Team -','','ultraedwin','ultraedwin','2011-08-01 17:19:57','Server Maintenance Notice');
